/-- The identifier passed to Lean to disambiguate the package's native symbols. -/
public def id? (self : Package) : Option PkgId :=
  if self.bootstrap then none else some <| self.origName.toString (escape := false)

def name_hash(name):
    h=1723
    for part in name.split('.'):h=mix(h,self.sdk_hash.string(part))
    return h
assert inputs[6]==['Module.name: '+module,f'{mix(1723,name_hash(module)):016x}']
assert inputs[7]==['Package.id?: (some Zeta23)',f'{mix(1723,mix(name_hash("Zeta23"),13)):016x}']
